import { useState } from 'react';
import { useForm } from 'react-hook-form';

type Draft = { displayName: string };
type Profile = Draft & { id: string };
type Props = {
  profile: Profile;
  save: (id: string, draft: Draft) => Promise<Draft>;
};

export function ProfileEditor({ profile, save }: Props) {
  const [notice, setNotice] = useState('');
  const { register, handleSubmit, reset, formState: { errors, isSubmitting } } =
    useForm<Draft>({ defaultValues: { displayName: profile.displayName } });

  const submit = handleSubmit(async (draft) => {
    setNotice('');
    try {
      const accepted = await save(profile.id, draft);
      reset(accepted);
      setNotice('Saved');
    } catch {
      setNotice('Save failed. Try again.');
    }
  });

  return <form onSubmit={submit} noValidate>
    <label htmlFor="display-name">Display name</label>
    <input id="display-name" {...register('displayName', { required: 'Enter a name' })}
      aria-invalid={Boolean(errors.displayName)} aria-describedby="name-error" />
    <p id="name-error" role="alert">{errors.displayName?.message}</p>
    <button type="submit" disabled={isSubmitting}>Save</button>
    <p role="status">{notice}</p>
  </form>;
}

