import { useState } from 'react';
import { useForm } from 'react-hook-form';

type Draft = { title: string };
type RecordValue = Draft & { id: string };
type Props = { record: RecordValue; save: (id: string, draft: Draft) => Promise<Draft> };

export function RenamePanel(props: Props) {
  return <RenameForm key={props.record.id} {...props} />;
}

function RenameForm({ record, save }: Props) {
  const [notice, setNotice] = useState('');
  const { register, handleSubmit, reset, formState: { errors, isSubmitting } } =
    useForm<Draft>({ defaultValues: { title: record.title } });
  const submit = handleSubmit(async (draft) => {
    setNotice('');
    try {
      const accepted = await save(record.id, draft);
      reset(accepted);
      setNotice('Saved');
    } catch {
      setNotice('Could not save. Your draft is still available.');
    }
  });
  return <form onSubmit={submit} noValidate>
    <label htmlFor="record-title">Title</label>
    <input id="record-title" readOnly={isSubmitting}
      {...register('title', { required: 'Enter a title' })}
      aria-invalid={Boolean(errors.title)} aria-describedby="title-error" />
    <p id="title-error" role="alert">{errors.title?.message}</p>
    <button type="submit" disabled={isSubmitting}>Save</button>
    <p role="status">{notice}</p>
  </form>;
}

