import { useState } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';

const pledgeSchema = z.object({
  monthlyAmount: z.coerce.number().int().min(0).max(10000).optional(),
});
type Draft = { monthlyAmount: string };
type Pledge = z.output<typeof pledgeSchema>;
type Props = { save: (pledge: Pledge) => Promise<void> };

export function PledgeForm({ save }: Props) {
  const [notice, setNotice] = useState('');
  const { register, handleSubmit, formState: { errors, isSubmitting } } =
    useForm<Draft, unknown, Pledge>({
      resolver: zodResolver(pledgeSchema),
      defaultValues: { monthlyAmount: '' },
    });
  const submit = handleSubmit(async (pledge) => {
    setNotice('');
    try {
      await save(pledge);
      setNotice('Preference saved');
    } catch {
      setNotice('Unable to save. Try again.');
    }
  });
  return <form onSubmit={submit} noValidate>
    <label htmlFor="monthly-amount">Monthly amount (optional)</label>
    <input id="monthly-amount" type="number" min="0" max="10000" step="1"
      readOnly={isSubmitting} {...register('monthlyAmount')}
      aria-invalid={Boolean(errors.monthlyAmount)} aria-describedby="amount-help amount-error" />
    <p id="amount-help">Leave blank for no preference. Enter 0 to choose no monthly payment.</p>
    <p id="amount-error" role="alert">{errors.monthlyAmount?.message}</p>
    <button type="submit" disabled={isSubmitting}>Save preference</button>
    <p role="status">{notice}</p>
  </form>;
}

