import { useState } from 'react';

type Task = { id: string; title: string; done: boolean };

export function AssignedTasks({ tasks }: { tasks: readonly Task[] }) {
  const [showCompleted, setShowCompleted] = useState(false);
  const visible = tasks.filter((task) => showCompleted || !task.done);
  return <section aria-labelledby="tasks-heading">
    <h2 id="tasks-heading">Assigned tasks</h2>
    <label><input type="checkbox" checked={showCompleted}
      onChange={(event) => setShowCompleted(event.target.checked)} />Show completed</label>
    {visible.length === 0 ? <p>No matching tasks.</p> : <ul>
      {visible.map((task) => <li key={task.id}>
        {task.title}{task.done ? ' (completed)' : ''}
      </li>)}
    </ul>}
  </section>;
}

