import { renderToStaticMarkup } from 'react-dom/server';

type Product = { slug: string; name: string; description: string };
const products: readonly Product[] = [
  { slug: 'linen-towel', name: 'Linen towel', description: 'An undyed woven linen towel.' },
];

export function handleProduct(slug: string): Response {
  const product = products.find((entry) => entry.slug === slug);
  const page = product ? <html lang="en"><head>
    <title>{product.name}</title>
    <meta name="description" content={product.description} />
    <link rel="canonical" href={`https://shop.example/products/${product.slug}`} />
  </head><body><main>
    <h1>{product.name}</h1><p>{product.description}</p><a href="/products">All products</a>
  </main></body></html> : <html lang="en"><head>
    <title>Product not found</title><meta name="robots" content="noindex" />
  </head><body><main>
    <h1>Product not found</h1><a href="/products">Browse products</a>
  </main></body></html>;
  return new Response('<!doctype html>' + renderToStaticMarkup(page), {
    status: 200,
    headers: { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'no-store' },
  });
}

