import { useState } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { EmailField } from './EmailField';

const schema = z.object({ email: z.string().email('Enter a valid email') });
type Registration = z.output<typeof schema>;
type Props = { onRegister: (value: Registration) => Promise<void> };

export function EmailRegistration({ onRegister }: Props) {
  const [notice, setNotice] = useState('');
  const { register, handleSubmit, formState: { errors, isSubmitting } } =
    useForm<Registration>({ resolver: zodResolver(schema), defaultValues: { email: '' } });
  const submit = handleSubmit(async (value) => {
    setNotice('');
    try {
      await onRegister(value);
      setNotice('Registration accepted');
    } catch {
      setNotice('Registration failed. Try again.');
    }
  });
  return <form onSubmit={submit} noValidate>
    <EmailField {...register('email')} error={errors.email?.message} readOnly={isSubmitting} />
    <button type="submit" disabled={isSubmitting}>Register</button>
    <p role="status">{notice}</p>
  </form>;
}

