import { useSyncExternalStore } from 'react';

export function createCounter() {
  let count = 0;
  const listeners = new Set<() => void>();
  return {
    getSnapshot: () => count,
    subscribe: (listener: () => void) => {
      listeners.add(listener);
      return () => { listeners.delete(listener); };
    },
    increment: () => {
      count += 1;
      listeners.forEach((listener) => listener());
    },
  };
}

export type CounterStore = ReturnType<typeof createCounter>;

export function Counter({ store }: { store: CounterStore }) {
  const count = useSyncExternalStore(store.subscribe, store.getSnapshot, store.getSnapshot);
  return <section aria-label="Counter">
    <p role="status">Count: {count}</p>
    <button type="button" onClick={store.increment}>Add one</button>
  </section>;
}

